WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE t.kind_id=1),
mi_counts AS MATERIALIZED (SELECT mi.movie_id, COUNT(*)::HUGEINT AS n FROM movie_info mi JOIN selected_titles eligible ON eligible.id=mi.movie_id WHERE mi.info_type_id=6 GROUP BY mi.movie_id)
SELECT COALESCE(SUM(mi.n),0) FROM selected_titles t JOIN mi_counts mi ON mi.movie_id=t.id;

